function validate([s]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 100) return 's needs 1 to 100 characters.';
  if (!/^[a-z0-9]+$/.test(s)) return 's may contain only lowercase letters and digits.';
  let balance = 0;
  for (const ch of s) {
    balance += ch >= '0' && ch <= '9' ? -1 : 1;
    if (balance < 0) return 'Each digit needs a letter before it that has not been erased yet.';
  }
  return null;
}

