function clearDigits(s) {
  // Apply the rule literally on the string: everything before the first digit is a letter,
  // so the nearest letter is the character right before it. Cut both out and repeat.
  let t = s;
  let first = t.search(/[0-9]/);
  while (first !== -1) {
    t = t.slice(0, first - 1) + t.slice(first + 1);
    first = t.search(/[0-9]/);
  }
  return t;
}

