function generate(rand, size) {
  const n = size === 'large' ? 100 : 1 + Math.floor(rand() * 12);
  const alphabet = size === 'large' ? 26 : 1 + Math.floor(rand() * 5);
  const digitRate = size === 'large' ? 0.45 : rand() * 0.6;
  let letters = 0;
  let digits = 0;
  let s = '';
  for (let i = 0; i < n; i++) {
    // A digit may only appear while some letter before it is still standing.
    if (letters > digits && rand() < digitRate) {
      s += String(Math.floor(rand() * 10));
      digits++;
    } else {
      s += String.fromCharCode(97 + Math.floor(rand() * alphabet));
      letters++;
    }
  }
  return [s];
}
